-- ---------- Bot knowledge sources (requirements 43, 45) ----------
-- Several sources are added by a second teacher of the course, which is
-- what requirement 45 allows.
INSERT IGNORE INTO bot_sources
    (source_id, bot_id, source_type, display_name, extracted_text,
     content_sha256, added_by_user_id, status, created_at,
     question_id, question_version_no, current_version_no) VALUES
  (401, 301, 'FREE_TEXT', 'Algebra revision notes',
   'Linear equations. To solve ax + b = c, subtract b from both sides and then divide by a. Always apply the same operation to both sides so the equality is preserved. Example: 3x + 7 = 22 gives 3x = 15 and x = 5.',
   'fa106a83fa630eef782ee53e6b7f066ba20d9be6a60305a83fd2f5239871d711', 1101, 'ACTIVE', @seed_now, NULL, NULL, 1),
  (402, 301, 'TXT', 'Geometry formula sheet',
   'Triangles. The interior angles of any triangle sum to 180 degrees. In a right triangle the square of the hypotenuse equals the sum of the squares of the other two sides. Circles. Circumference is 2*pi*r and area is pi*r^2.',
   'f2f5984c1503a9e380ba54134863a902f8f1bdb4c107c08037d3982fdf899f40', 1102, 'ACTIVE', @seed_now, NULL, NULL, 1),
  (403, 301, 'FREE_TEXT', 'Quadratic equations',
   'A quadratic has the form ax^2 + bx + c = 0. Its roots are given by x = (-b +/- sqrt(b^2 - 4ac)) / 2a. The expression under the square root is the discriminant: positive gives two real roots, zero gives one, negative gives none.',
   '103913e0f621465845cf21ba26257ddc46117bfb7c0ca3380cae971e6712e2d3', 1101, 'ACTIVE', @seed_now, NULL, NULL, 1),
  (404, 302, 'FREE_TEXT', 'Mechanics revision notes',
   'Newton''s laws of motion. A body stays at rest or in uniform motion unless a net force acts on it. Acceleration is proportional to the net force and inversely proportional to mass, written F = ma. Every action has an equal and opposite reaction.',
   '30a4a1ed566956186661807a02cf8db8c7cf05c1afca9a01893103d59836407d', 1104, 'ACTIVE', @seed_now, NULL, NULL, 1),
  (405, 302, 'DOCX', 'Exam technique handout',
   'Read every question twice before answering. Where a calculation is needed, write the intermediate steps so a small slip does not cost the whole answer. Leave hard questions until the end.',
   'f16ec106fe5683597caea7fb0b0625a352a42f9902f44f721220efc0ad402f73', 1101, 'ACTIVE', @seed_now, NULL, NULL, 1),
  (406, 303, 'FREE_TEXT', 'Grammar reference',
   'The present simple describes habits and general truths, and takes an s in the third person singular: she goes, he writes. The past simple of an irregular verb must be learned: write becomes wrote, begin becomes began.',
   'c53104f83d281feacda2b5fa6ec6bd385a3b393ce0e56d5d1cd0d1c2335eeeda', 1102, 'ACTIVE', @seed_now, NULL, NULL, 1);

