-- ---------- Verification ----------
SELECT 'subjects' AS entity, COUNT(*) AS rows_present FROM subjects
UNION ALL SELECT 'courses', COUNT(*) FROM courses
UNION ALL SELECT 'users', COUNT(*) FROM users
UNION ALL SELECT 'teacher_courses', COUNT(*) FROM teacher_courses
UNION ALL SELECT 'student_courses', COUNT(*) FROM student_courses
UNION ALL SELECT 'questions', COUNT(*) FROM questions
UNION ALL SELECT 'exams', COUNT(*) FROM exams
UNION ALL SELECT 'exam_executions', COUNT(*) FROM exam_executions
UNION ALL SELECT 'exam_submissions', COUNT(*) FROM exam_submissions
UNION ALL SELECT 'student_answers', COUNT(*) FROM student_answers
UNION ALL SELECT 'course_bots', COUNT(*) FROM course_bots
UNION ALL SELECT 'bot_sources', COUNT(*) FROM bot_sources
UNION ALL SELECT 'bot_conversations', COUNT(*) FROM bot_conversations
UNION ALL SELECT 'bot_messages', COUNT(*) FROM bot_messages
UNION ALL SELECT 'notifications', COUNT(*) FROM notifications
;

